def island_count(grid):
    R, C = len(grid), len(grid[0])
    seen = set()
    def dfs(r,c):
        if r<0 or c<0 or r>=R or c>=C: return
        if (r,c) in seen or grid[r][c]==0: return
        seen.add((r,c))
        for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)):
            dfs(r+dr, c+dc)
    n = 0
    for r in range(R):
        for c in range(C):
            if grid[r][c]==1 and (r,c) not in seen:
                n+=1; dfs(r,c)
    return n
print(island_count([[1,1,0,0],[1,0,0,1],[0,0,1,1]]))
